#!/usr/bin/env bash
# Stage versioned post-processor artifacts for release / CI.
#
# Usage:
#   ./dist/stage-post-processors.sh <BUILD_VERSION> [OUT_DIR]
#
# Reads sources from post-processors/, substitutes %%NXT_VERSION%% with BUILD_VERSION
# (release line e.g. v0.6.0), writes dist/post-processors-staging.env for CI.

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
BUILD_VERSION="${1:?BUILD_VERSION required (e.g. v0.6.0 or v0.6.0-beta.5)}"
OUT_DIR="${2:-${ROOT}/dist/post-processors/${BUILD_VERSION}}"
MANIFEST="${ROOT}/dist/post-processors-staging.env"

F360_CPS_NAME="nxt-${BUILD_VERSION}-f360.cps"
FREECAD_PY_NAME="nxt-${BUILD_VERSION}_post.py"
MCH_NAME="milo-v1.5-std.mch"

SRC_F360="${ROOT}/post-processors/fusion-360/nxt.cps"
SRC_FREECAD="${ROOT}/post-processors/freecad/nxt_post.py"
SRC_MCH="${ROOT}/post-processors/fusion-360/milo-v1.5-std.mch"

for f in "${SRC_F360}" "${SRC_FREECAD}" "${SRC_MCH}"; do
  if [[ ! -f "${f}" ]]; then
    echo "error: missing post-processor source: ${f}" >&2
    exit 1
  fi
done

rm -rf "${OUT_DIR}"
mkdir -p "${OUT_DIR}"

substitute_placeholders() {
  local src="$1"
  local dest="$2"
  sed "s/%%NXT_VERSION%%/${BUILD_VERSION}/g" "${src}" > "${dest}"
}

substitute_placeholders "${SRC_F360}" "${OUT_DIR}/${F360_CPS_NAME}"
substitute_placeholders "${SRC_FREECAD}" "${OUT_DIR}/${FREECAD_PY_NAME}"
substitute_placeholders "${SRC_MCH}" "${OUT_DIR}/${MCH_NAME}"

if grep -rq '%%NXT_VERSION%%' "${OUT_DIR}" 2>/dev/null; then
  echo "error: unreplaced %%NXT_VERSION%% in staged post-processors under ${OUT_DIR}" >&2
  grep -rn '%%NXT_VERSION%%' "${OUT_DIR}" >&2 || true
  exit 1
fi

cat > "${MANIFEST}" <<EOF
# Generated by dist/stage-post-processors.sh — do not commit
NXT_BUILD_VERSION=${BUILD_VERSION}
NXT_PP_DIR=${OUT_DIR}
NXT_PP_CPS=${OUT_DIR}/${F360_CPS_NAME}
NXT_PP_PY=${OUT_DIR}/${FREECAD_PY_NAME}
NXT_PP_MCH=${OUT_DIR}/${MCH_NAME}
EOF

echo "Staged post-processors for ${BUILD_VERSION} in ${OUT_DIR}"
echo "  ${F360_CPS_NAME}"
echo "  ${FREECAD_PY_NAME}"
echo "  ${MCH_NAME}"
